// In-memory table. fetchBatch returns copies of rows with id > afterId, ordered by id.
export function createDb(rows) {
  const data = new Map(rows.map((r) => [r.id, { ...r }]));
  const db = {
    updates: 0, failAfter: Infinity, onFetch: null,
    fetchBatch(afterId, limit) {
      const out = [...data.values()].filter((r) => r.id > afterId).sort((a, b) => a.id - b.id).slice(0, limit).map((r) => ({ ...r }));
      db.onFetch?.(out);
      return out;
    },
    update(id, fields) {
      if (db.updates >= db.failAfter) throw new Error('crash');
      db.updates++;
      Object.assign(data.get(id), fields);
    },
    insert(row) { data.set(row.id, { ...row }); },
    all: () => [...data.values()].map((r) => ({ ...r })),
  };
  return db;
}

