import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { backfillSlugs } from '../src/migrate.js';
const rows = () => [1, 2, 3, 4, 5].map((id) => ({ id, title: 'Post Number ' + id }));
test('every row gets a slug from its title', () => {
  const db = createDb(rows());
  backfillSlugs(db);
  expect(db.all().map((r) => r.slug)).toEqual(['post-number-1', 'post-number-2', 'post-number-3', 'post-number-4', 'post-number-5']);
});
test('works with other batch sizes and an empty table', () => {
  const db = createDb(rows());
  backfillSlugs(db, 1);
  expect(db.all().every((r) => r.slug)).toBe(true);
  expect(() => backfillSlugs(createDb([]), 3)).not.toThrow();
});

