import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { backfillSlugs } from '../src/migrate.js';
const rows = () => [1, 2, 3, 4, 5, 6].map((id) => ({ id, title: 'Post ' + id, ...(id === 2 ? { slug: 'custom-two' } : {}) }));
const slugs = (db) => db.all().map((r) => r.slug);
const WANT = ['post-1', 'custom-two', 'post-3', 'post-4', 'post-5', 'post-6'];
test('a row that already has a slug keeps it', () => {
  const db = createDb(rows());
  backfillSlugs(db);
  expect(slugs(db)).toEqual(WANT);
});
test('after a crash half way, a re-run finishes the job and only does the remaining work', () => {
  const db = createDb(rows());
  db.failAfter = 3;
  expect(() => backfillSlugs(db)).toThrow();
  const remaining = db.all().filter((r) => !r.slug).length;
  db.failAfter = Infinity;
  db.updates = 0;
  backfillSlugs(db);
  expect(slugs(db)).toEqual(WANT);
  expect(db.updates).toBe(remaining);
});
test('running it again changes nothing', () => {
  const db = createDb(rows());
  backfillSlugs(db);
  db.updates = 0;
  backfillSlugs(db);
  expect(db.updates).toBe(0);
  expect(slugs(db)).toEqual(WANT);
});
test('a row added while it runs is not skipped', () => {
  const db = createDb(rows());
  let added = false;
  db.onFetch = () => { if (!added) { added = true; db.insert({ id: 100, title: 'Late Row' }); } };
  backfillSlugs(db, 2);
  expect(db.all().find((r) => r.id === 100).slug).toBe('late-row');
});
